import{t,subscribeLanguage}from './i18n.js';
import{uiLeaf,uiAttribute,uiTextAttributes,setUiMessage,uiMessage,uiError,setUiAttribute}from './ui.js';
import{paintLessonsUi,bindLessonsUi,lessonDateLabel,lessonDateMarkup,lessonDueMarkup,lessonErrorMessage,lessonErrorText,lessonUiError,lessonMessageMarkup}from './lessons-ui.js';
import{mountTeacherWork}from './homework-work.js';
import{homeworkMarkup,mountHomeworkEditor}from './lesson-homework.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const codePattern=/^[\w-]{32}$/;
export const classroomInviteUrl=code=>codePattern.test(code||'')?'https://skodytunez-maker.github.io/salah/#lesson?invite='+code:null;
export function mountLessonPlans({root,api,post,onStart,notify=()=>{},now=Date.now}){
 const doc=root.ownerDocument,section=doc.createElement('section');section.className='lesson-plans';section.innerHTML="<div class=\"lesson-plan-heading\"><div><span class=\"lesson-overline\">"+uiLeaf("lessonUi.planSchedule")+"</span><h2>"+uiLeaf("lessonUi.planTitle")+"</h2></div><button type=\"button\" class=\"button\" data-new>"+uiLeaf("lessonUi.planNew")+"</button></div><p class=\"lesson-note\">"+uiLeaf("lessonUi.planHelp")+"</p><div data-form></div><div data-list role=\"status\">"+uiLeaf("lessonUi.planLoading")+"</div><div data-homework></div><div data-invite></div>";
 root.querySelector('.lesson-list')?.before(section);
 let stopHomework=null;const homeworkHost=section.querySelector('[data-homework]');function closeHomework(){stopHomework?.();stopHomework=null;homeworkHost.replaceChildren();}function showWorks(row){closeHomework();stopHomework=mountTeacherWork(homeworkHost,{lesson:row,call:(action,data)=>post('plans/'+row.id+'/'+action,data),isActive:active});homeworkHost.scrollIntoView?.({block:'nearest'});}function editHomework(row){closeHomework();stopHomework=mountHomeworkEditor(homeworkHost,{lesson:row,onCancel:closeHomework,onSave:async(homework,expectedHomeworkRevision)=>{await post('plans/'+row.id+'/homework',{homework,expectedHomeworkRevision});if(active()){closeHomework();await refresh();}}});homeworkHost.scrollIntoView?.({block:'nearest'});}
 let disposed=false,revision=0;const active=()=>!disposed&&section.isConnected,formHost=section.querySelector('[data-form]'),list=section.querySelector('[data-list]'),invitation=section.querySelector('[data-invite]');
 const format=l=>lessonDateLabel(l);
 function paintPlanLabels(){for(const [name,key]of [['minutes','lessonUi.planMinutes'],['maxParticipants','lessonUi.planParticipantsOption']]){const select=formHost.querySelector('select[name='+name+']');if(!select)continue;const value=select.value;for(const option of select.options){const label=t(key,{count:Number(option.value)});if(option.textContent!==label){if(option.childNodes.length===1&&option.firstChild.nodeType===3)option.firstChild.data=label;else option.textContent=label;}}if(select.value!==value)select.value=value;}}
 function form(row=null){
  const zone=row?.timeZone||Intl.DateTimeFormat().resolvedOptions().timeZone;
  let date=row?.date||new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).format(now());
  if(!row&&new Intl.DateTimeFormat('en-GB',{timeZone:zone,hour:'2-digit',hourCycle:'h23'}).format(now())>='20')date=new Date(Date.parse(date+'T12:00:00Z')+86400000).toISOString().slice(0,10);
  formHost.innerHTML='<form class="lesson-form lesson-plan-form"><h2>'+uiLeaf(row?'lessonUi.planEdit':'lessonUi.planCreate')+"</h2><label>"+uiLeaf("lessonUi.planTopic")+"<input name=\"title\" translate=\"no\" dir=\"auto\" maxlength=\"100\" required value=\""+esc(row?.title||'')+"\" "+uiAttribute("lessonUi.planTopicPlaceholder",{},"placeholder")+"></label><label>"+uiLeaf("lessonUi.planTeacher")+"<input name=\"teacherName\" translate=\"no\" dir=\"auto\" maxlength=\"48\" required value=\""+esc(row?.teacherName||'')+"\"></label><div class=\"lesson-plan-fields\"><label>"+uiLeaf("lessonUi.planDate")+"<input name=\"date\" type=\"date\" dir=\"ltr\" required value=\""+esc(date)+"\"></label><label>"+uiLeaf("lessonUi.planStartTime")+"<input name=\"time\" type=\"time\" dir=\"ltr\" required value=\""+esc(row?.time||'20:00')+"\"></label></div><label>"+uiLeaf("lessonUi.planTimezone")+"<input name=\"timeZone\" dir=\"ltr\" translate=\"no\" required maxlength=\"80\" value=\""+esc(zone)+"\"><small>"+uiLeaf("lessonUi.planTimezoneHelp")+"</small></label><div class=\"lesson-plan-fields\"><label>"+uiLeaf("lessonUi.planDuration")+"<select name=\"minutes\">"+[30,45,60,90].map(n=>'<option value="'+n+'"'+((row?.minutes||60)===n?' selected':'')+'>'+esc(t('lessonUi.planMinutes',{count:n}))+'</option>').join('')+"</select></label><label>"+uiLeaf("lessonUi.planParticipants")+"<select name=\"maxParticipants\">"+Array.from({length:9},(_,i)=>i+2).map(n=>'<option value="'+n+'"'+((row?.maxParticipants||10)===n?' selected':'')+'>'+esc(t('lessonUi.planParticipantsOption',{count:n}))+'</option>').join('')+"</select></label></div><label>"+uiLeaf("lessonUi.planRemind")+"<input name=\"reminderTime\" type=\"time\" dir=\"ltr\" required value=\""+esc(row?.reminderTime||'17:00')+"\"></label><p class=\"lesson-note\">"+uiLeaf("lessonUi.planReminderHelp")+"</p><p class=\"lesson-error\" role=\"alert\"></p><div class=\"button-row\"><button type=\"submit\" class=\"button\">"+uiLeaf("lessonUi.planSave")+"</button><button type=\"button\" class=\"lesson-text-button\" data-cancel-form>"+uiLeaf("lessonUi.planCancel")+"</button></div></form>";
  const f=formHost.querySelector('form');f.querySelector('[data-cancel-form]').onclick=()=>formHost.replaceChildren();
  f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('[type=submit]');if(b.disabled)return;b.disabled=true;const data=Object.fromEntries(new FormData(f));data.minutes=Number(data.minutes);data.maxParticipants=Number(data.maxParticipants);try{await post(row?'plans/'+row.id+'/update':'plans',data);if(active()){formHost.replaceChildren();await refresh();}}catch(error){if(active()){setUiMessage(f.querySelector('[role=alert]'),lessonErrorMessage(error));b.disabled=false;}}};
  paintPlanLabels();f.querySelector('input').focus();
 }
 async function invite(row,b){b.disabled=true;try{const value=await post('plans/'+row.id+'/invite');const url=classroomInviteUrl(value.code);if(!url)throw lessonUiError('Приглашение пока недоступно.','lessonUi.planInviteUnavailable');if(!active())return;invitation.innerHTML="<section class=\"lesson-invite-box\"><div class=\"lesson-invite-head\"><strong>"+uiLeaf("lessonUi.planSharedLink")+"</strong><button type=\"button\" class=\"lesson-invite-close\" "+uiAttribute("lessonUi.planCloseInvite",{},"aria-label")+">×</button></div><p>"+uiLeaf("lessonUi.planInviteHelp")+"</p><input readonly dir=\"ltr\" translate=\"no\" "+uiAttribute("lessonUi.planLessonLink",{},"aria-label")+" value=\""+esc(url)+"\"><button class=\"button\" type=\"button\" data-copy>"+uiLeaf("lessonUi.planCopyInvite")+"</button><p role=\"status\"></p></section>";invitation.querySelector('.lesson-invite-close').onclick=()=>invitation.replaceChildren();invitation.querySelector('[data-copy]').onclick=async()=>{try{await navigator.clipboard.writeText(url);if(active())setUiMessage(invitation.querySelector('[role=status]'),uiMessage('lessonUi.planCopied'));}catch{if(active()){invitation.querySelector('input').select();setUiMessage(invitation.querySelector('[role=status]'),uiMessage('lessonUi.planCopyManually'));}}};}catch(e){notify(lessonErrorText(e));}finally{b.disabled=false;}}
 async function refresh(){
  const rev=++revision;try{const rows=await api('plans');if(!active()||rev!==revision)return;list.replaceChildren();if(!rows.length){list.innerHTML=uiLeaf('lessonUi.planEmpty');return;}
   for(const row of rows){const card=doc.createElement('article');card.className='lesson-card lesson-plan-card';const ended=['cancelled','ended'].includes(row.state);card.innerHTML='<div><span class="lesson-live-label">'+uiLeaf({planned:'lessonUi.planPlanned',live:'lessonUi.planLive',ended:'lessonUi.planEnded',cancelled:'lessonUi.planCancelled'}[row.state]||'lessonUi.planLesson')+'</span><h3 translate="no" dir="auto">'+esc(row.title)+'</h3><p>'+lessonDateMarkup(row)+' · '+esc(row.timeZone)+'</p><p translate="no" dir="auto">'+uiLeaf('lessonUi.planParticipantLimit',{name:row.teacherName,count:row.maxParticipants})+'</p><small>'+uiLeaf('lessonUi.planReminderAt',{time:row.reminderTime})+'</small></div><div class="lesson-plan-actions"></div>';const actions=card.querySelector('.lesson-plan-actions');
    const add=(text,run,disabled=false)=>{const b=doc.createElement('button');b.className='button secondary';b.type='button';setUiMessage(b,uiMessage(text));b.disabled=disabled;b.onclick=()=>run(b);actions.append(b);return b;};
    if(!ended){add('lessonUi.planInvite',b=>invite(row,b),!row.hasInvite);if(row.state==='planned'){add('lessonUi.planChange',()=>form(row));let confirming=false;add('lessonUi.planCancelLesson',async b=>{if(!confirming){confirming=true;setUiMessage(b,uiMessage('lessonUi.planConfirmCancel'));return;}b.disabled=true;try{await post('plans/'+row.id+'/cancel');await refresh();}catch(e){notify(lessonErrorText(e));b.disabled=false;}});}add(row.state==='live'?'lessonUi.planOpenRoom':'lessonUi.planStartLesson',async b=>{b.disabled=true;try{const l=await post('plans/'+row.id+'/start');if(active())await onStart(l.id);}catch(e){notify(lessonErrorText(e));b.disabled=false;}},now()<row.startsAt-15*60000||now()>=row.endsAt);}
    if(row.state!=='cancelled'){add(row.homework?'lessonUi.planEditHomework':'lessonUi.planAddHomework',()=>editHomework(row));if(row.homework)add('lessonUi.planStudentWorks',()=>showWorks(row));const box=doc.createElement('div');box.innerHTML=homeworkMarkup(row.homework);card.append(...box.childNodes);}
    list.append(card);
   }
  }catch(e){if(active()&&rev===revision){list.innerHTML=lessonMessageMarkup(e);const retry=doc.createElement('button');retry.type='button';retry.className='lesson-text-button';setUiMessage(retry,uiMessage('lessonUi.planRetry'));retry.onclick=()=>void refresh();list.append(retry);}}
 }
 const offLanguage=bindLessonsUi(section,paintPlanLabels);section.querySelector('[data-new]').onclick=()=>form();void refresh();
 return()=>{disposed=true;offLanguage();revision++;closeHomework();section.remove();};
}
